/* App Layout Styles */

.app-container {
  position: relative;
  min-height: 100vh;
  background-color: #f8fafc;
  color: #0f172a;
  font-family: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  transition-property: color, background-color;
  transition-duration: 300ms;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

.app-container::selection {
  background-color: #a855f7;
  color: #ffffff;
}

.dark .app-container {
  background-color: #09090b;
  color: #f5f5f5;
}

.app-main {
  transition-property: opacity;
  transition-duration: 700ms;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  opacity: 1;
}

.app-main--loading {
  opacity: 0;
  pointer-events: none;
}

import React, { useState } from "react";
import { Analytics } from "@vercel/analytics/react";
import { ThemeProvider } from "@/context/ThemeContext";
import { LoadingScreen } from "@/components/sections/LoadingScreen";
import { Navbar } from "@/components/sections/Navbar";
import { Hero } from "@/components/sections/Hero";
import { About } from "@/components/sections/About";
import { Experience } from "@/components/sections/Experience";
import { Projects } from "@/components/sections/Projects";
import { Skills } from "@/components/sections/Skills";
import { Achievements } from "@/components/sections/Achievements";
import { Contact } from "@/components/sections/Contact";
import { Footer } from "@/components/sections/Footer";
import "./App.css";

export default function App() {
  const [loading, setLoading] = useState(true);

  return (
    <ThemeProvider>
      <div className="app-container">
        {/* 1. Loading Terminal Screen (Appears once) */}
        <LoadingScreen onComplete={() => setLoading(false)} />

        {/* Main Website Portfolio Content */}
        <main className={`app-main ${loading ? "app-main--loading" : ""}`}>
          {/* 2. Floating Dock Navbar */}
          <Navbar />

          {/* 3. Hero Section */}
          <Hero startAnimation={!loading} />

          {/* 4. About Me (Draggable Cards) */}
          <About />

          {/* 5. Experience (Skiper52 Expand on Hover) */}
          <Experience />

          {/* 6. Projects (Following Pointer Cards & Modals) */}
          <Projects />

          {/* 7. Skills (Categorized Stack & Brand Badges) */}
          <Skills />

          {/* 8. Achievements & Certifications (Carousel) */}
          <Achievements />

          {/* 9. Contact */}
          <Contact />

          {/* 10. Footer */}
          <Footer />
        </main>
        <Analytics />
      </div>
    </ThemeProvider>
  );
}

/* About Component Dedicated Styles */

.about__section {
  position: relative;
  width: 100%;
  padding-top: 50px;
  padding-bottom: 5rem;
  padding-left: 1rem;
  padding-right: 1rem;
}

.about__container {
  margin-left: auto;
  margin-right: auto;
  max-width: 72rem;
}

.about__header {
  text-align: center;
}

.about__title {
  margin-top: 1rem;
  font-size: 1.875rem;
  font-weight: 800;
  color: #0f172a;
}

.dark .about__title {
  color: #ffffff;
}

@media (min-width: 640px) {
